      </div>
    </div>
  </div>

  <!-- Key Point -->
  <div class="bg-gradient-to-r from-amber-50 to-orange-50 rounded-2xl p-6 border-l-4 border-amber-400">
    <div class="flex items-start gap-4">
      <div class="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">A working six-step process is more useful than a complicated twenty-step process that nobody uses. Start simple, test thoroughly, then improve.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Module 9 Complete</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Map Your Journey</p>
          <p class="text-slate-600 text-sm">Choose one real customer journey and map it using the eight LeadProspectrr parts.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Answer the Questions</p>
          <p class="text-slate-600 text-sm">How do they enter? What is captured? How are they organized? What communication happens? When do they become an opportunity? What pipeline stage? What follow-up? How do they book? How do they buy? What happens after? What will you measure?</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Build and Test</p>
          <p class="text-slate-600 text-sm">Use your own email address to test the complete journey from form to pipeline.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Build Your First Connected CRM Journey',
      lesson_number = 10,
      sort_order = 10,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Build Your First Connected CRM Journey';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Build Your First Connected CRM Journey

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 9 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 9 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-connected-journey' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-connected-journey not found in module 9';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the recommended beginner setup order?', 
    '["Start with complex workflows first","Contacts, fields, tags, pipeline, calendar, form, confirmation, workflow, test, review","Only set up payments","Do everything at once"]'::jsonb,
    'Contacts, fields, tags, pipeline, calendar, form, confirmation, workflow, test, review',
    'The recommended order is: add contacts, create fields, create tags, set up pipeline, connect calendar, create form, create confirmation, create workflow, test, and review.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why test with your own email?', 
    '["To spam yourself","To experience the journey as a real lead would and catch any issues","It is required by law","To delete the test data"]'::jsonb,
    'To experience the journey as a real lead would and catch any issues',
    'Testing with your own email lets you experience the complete journey as a real lead would, helping you catch issues before real prospects encounter them.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is better: a simple six-step process or a complex twenty-step process?', 
    '["The complex twenty-step process","A working six-step process is more useful than a complicated process nobody uses","Neither is useful","It depends on the weather"]'::jsonb,
    'A working six-step process is more useful than a complicated process nobody uses',
    'A simple working process is always better than a complex one that is too difficult to use. Start simple, get it working, then add complexity only if needed.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
